create table if not exists public.teaching_vacancies (id text primary key,title text not null,school text not null,country text not null,region text,subject text not null,level text not null,employment text,salary text,deadline text,description text,requirements text,apply_url text not null,featured boolean default false,status text default 'published',created_at timestamptz default now(),updated_at timestamptz default now()); alter table public.teaching_vacancies enable row level security; drop policy if exists "Public published teaching vacancies" on public.teaching_vacancies; create policy "Public published teaching vacancies" on public.teaching_vacancies for select using (status='published');